1	//! Prompt assembly (`codex-consult.ps1:2352-2429`).
2	//!
3	//! The structured-mode prompt OPENS with the fixed FINAL OUTPUT CONTRACT paragraph, then the
4	//! ask, the brief pointer, an optional range line, the purpose paragraph, the open-findings
5	//! snapshot, the reply-format/schema block (with the schema text inlined when the transport
6	//! is prompt-only), the constraints line, and always ends with `Consultation id: <id>`. A
7	//! `-Raw` (or `-Purpose chore`) prompt carries none of the structured scaffolding.
8	//!
9	//! Parts are joined by a blank line; the line ending is CRLF (`$nl = "\r\n"`), matching the
10	//! plugin so the prompt travels byte-for-byte.
11	
12	/// The per-purpose presets (`$presetEffort`/`$presetWords`/`$presetTimeout`, purpose text).
13	pub mod presets {
14	    /// The valid purposes.
15	    pub const VALID: [&str; 8] = [
16	        "framing",
17	        "decision",
18	        "checkpoint",
19	        "core-contract",
20	        "acceptance",
21	        "diff-review",
22	        "stuck",
23	        "chore",
24	    ];
25	
26	    /// The default effort for a purpose (`""` = no purpose).
27	    pub fn effort(purpose: &str) -> &'static str {
28	        match purpose {
29	            "framing" | "decision" | "acceptance" | "diff-review" => "high",
30	            "checkpoint" => "medium",
31	            "core-contract" | "stuck" => "xhigh",
32	            "chore" => "low",
33	            _ => "high",
34	        }
35	    }
36	
37	    /// The default word budget for a purpose.
38	    pub fn words(purpose: &str) -> u32 {
39	        match purpose {
40	            "checkpoint" => 500,
41	            "core-contract" | "acceptance" => 900,
42	            "chore" => 400,
43	            _ => 700,
44	        }
45	    }
46	
47	    /// The default timeout (seconds) for a purpose (`""` = no purpose → 900).
48	    pub fn timeout(purpose: &str) -> i64 {
49	        match purpose {
50	            "framing" | "decision" => 1800,
51	            "core-contract" | "diff-review" | "stuck" => 2400,
52	            "acceptance" => 3600,
53	            "chore" => 600,
54	            _ => 900,
55	        }
56	    }
57	
58	    /// The purpose paragraph appended to the prompt. (wave 8 = plugin wave 30, T15) The paragraphs
59	    /// of the reviewing purposes (checkpoint, core-contract, acceptance, diff-review) end with the
60	    /// reading discipline ([`c3_core::quota::READING_DISCIPLINE`]): a reviewer that prints whole
61	    /// files replays them on every later tool call of its thread.
62	    pub fn text(purpose: &str) -> String {
63	        let base = base_text(purpose);
64	        if c3_core::quota::READING_DISCIPLINE_PURPOSES.contains(&purpose) {
65	            format!("{base} {}", c3_core::quota::READING_DISCIPLINE)
66	        } else {
67	            base.to_string()
68	        }
69	    }
70	
71	    /// The purpose paragraph without the reading discipline.
72	    fn base_text(purpose: &str) -> &'static str {
73	        match purpose {
74	            "framing" => "Surface the options the brief does not list and challenge the framing itself before answering inside it. Say what you would need to know to choose between the options.",
75	            "decision" => "Rank the alternatives. For each one, name the deciding factor and its failure mode.",
76	            "checkpoint" => "Verify the CURRENT invariants the brief claims against the code as it is now, and report any drift between what is claimed and what exists. Keep it short.",
77	            "core-contract" => "This review runs BEFORE dependent work is built on the core. Cover the interfaces, recovery and persistence paths and the state machines NAMED IN THE BRIEF and their immediate dependency boundaries - not the whole system. For each state machine: states, transitions, the failure at each transition. Name what the evidence does not show. Expect this review to be re-run whenever recovery, persistence or interfaces change.",
78	            "acceptance" => "Decide whether the result can be accepted. The verdict, the blockers, the unproven scenarios and an OBSERVABLE first-run checklist (what must be seen in logs or output on the first real run before an exit code 0 is believed) are mandatory.",
79	            "diff-review" => "Read the change adversarially: what breaks, what it does not cover, what the tests do not prove.",
80	            "stuck" => "The coordinator is stuck. Look for the angle they are missing and question their assumptions before proposing fixes.",
81	            "chore" => "This is a chore: a bounded search or extraction task. Report facts with file paths and line numbers, quote what you found, say what you did not find. No verdict, no findings, no recommendations beyond the ask.",
82	            _ => "",
83	        }
84	    }
85	
86	    /// The verdict rule phrase for a purpose (`acceptance`/`diff-review` allow the full set).
87	    pub fn verdict_rule(purpose: &str) -> &'static str {
88	        if purpose == "acceptance" || purpose == "diff-review" {
89	            "ACCEPT, HOLD or REJECT"
90	        } else {
91	            "ADVISE"
92	        }
93	    }
94	}
