96	/// The fixed opening paragraph of a structured-mode prompt.
97	pub const FINAL_OUTPUT_CONTRACT: &str = "FINAL OUTPUT CONTRACT: your ENTIRE final message must be exactly one bare JSON object (schema_version \"1\") - no code fence, no text before or after it. The Markdown answer lives only inside its reply_markdown string; each defect goes in findings[]. A prose final message cannot be ingested, however good the answer is.";
98	
99	/// One open finding as it appears in the prompt's snapshot.
100	pub struct OpenFinding {
101	    pub id: String,
102	    pub status: String,
103	    /// Already-rendered `Format-Locations` string.
104	    pub locations: String,
105	    pub claim: String,
106	    pub trigger: String,
107	    pub verification: String,
108	}
