110	/// A measured range for the range line.
111	pub struct Range {
112	    pub spec: String,
113	    /// The `<a>..<b>` / `<a>...<b>` human text.
114	    pub text: String,
115	    pub insertions: i64,
116	    pub deletions: i64,
117	}
