119	/// Everything the prompt needs.
120	pub struct PromptInputs<'a> {
121	    pub raw: bool,
122	    pub purpose: &'a str,
123	    pub prompt: &'a str,
124	    /// The repo-relative brief path (empty when none).
125	    pub brief_ref: &'a str,
126	    /// (0.2.4) The brief's text, inlined after the "Read the brief at" line for an engine whose
127	    /// spec says `inline_brief` (grok); empty otherwise.
128	    pub brief_text: &'a str,
129	    pub range: Option<&'a Range>,
130	    pub open_findings: &'a [OpenFinding],
131	    /// `output-schema` | `native` | `prompt-only`.
132	    pub schema_transport: &'a str,
133	    /// The reply schema text, inlined only when the transport is prompt-only.
134	    pub schema_text: &'a str,
135	    pub max_words: u32,
136	    pub consult_id: &'a str,
137	    /// The engine's `Tools:` line (D11), added after the ask/brief/range for a non-codex
138	    /// engine; empty for codex.
139	    pub tools_line: &'a str,
140	    /// A panel member's role paragraph (`role_prompt_line`), added after the ask and before the
141	    /// brief (`codex-consult.ps1:3555`); empty when the run has no role.
142	    pub role_line: &'a str,
143	    /// (wave 26b, D16) the reviewer's context-window line, added right after the ask when its
144	    /// roster entry names a `context_tokens`; empty otherwise.
145	    pub context_line: &'a str,
146	    /// (wave 26b, D16) the "your previous reply is <path>" line, added when a fork/resume was
147	    /// downgraded to a new thread because the previous one is too large; empty otherwise.
148	    pub prev_reply_line: &'a str,
149	    /// (wave 28c D11, 28d D7, 28e E4) the re-read anchor ([`reread_line`]), the last line before
150	    /// the consultation id; empty otherwise.
151	    pub reread_line: &'a str,
152	}
153	
154	const NL: &str = "\r\n";
155	
156	/// Assemble the full prompt text.
157	pub fn assemble(inp: &PromptInputs) -> String {
158	    let mut parts: Vec<String> = Vec::new();
159	    if !inp.raw {
160	        parts.push(FINAL_OUTPUT_CONTRACT.to_string());
161	    }
162	    if !inp.prompt.is_empty() {
163	        parts.push(inp.prompt.trim().to_string());
164	    }
165	    // (wave 26b, D16) a reviewer with a known context window is told so, right after the ask.
166	    if !inp.context_line.is_empty() {
167	        parts.push(inp.context_line.to_string());
168	    }
169	    // (wave 26b, D16) a downgraded fork/resume names the previous reply to re-read.
170	    if !inp.prev_reply_line.is_empty() {
171	        parts.push(inp.prev_reply_line.to_string());
172	    }
173	    // A panel member's role goes after the ask, before the brief (never inside the contract).
174	    if !inp.role_line.is_empty() {
175	        parts.push(inp.role_line.to_string());
176	    }
177	    if !inp.brief_ref.is_empty() {
178	        parts.push(format!(
179	            "Read the brief at `{}` (path relative to the repository root, which is your working directory) and answer every numbered question in it.",
180	            inp.brief_ref
181	        ));
182	        // (0.2.4) a grok turn may answer without opening the file: the text travels too.
183	        if !inp.brief_text.trim().is_empty() {
184	            parts.push(format!(
185	                "The brief's full text, the same file inlined so you have it even without a tool call (open the files it points to with your tools):{NL}<brief path=\"{}\">{NL}{}{NL}</brief>",
186	                inp.brief_ref,
187	                inp.brief_text.trim_end()
188	            ));
189	        }
190	    }
191	    if let Some(r) = inp.range {
192	        parts.push(format!(
193	            "Review range: `{}` - {} ({} insertions, {} deletions; git diff --shortstat). Plan your reading for its size.",
194	            r.spec, r.text, r.insertions, r.deletions
195	        ));
196	    }
197	    // The engine's own tools line (D11), after the ask/brief/range; empty for codex.
198	    if !inp.tools_line.is_empty() {
199	        parts.push(inp.tools_line.to_string());
200	    }
201	    if inp.raw {
202	        if inp.purpose == "chore" {
203	            parts.push(format!("Review purpose: chore. {}", presets::text("chore")));
204	        }
205	        parts.push(format!(
206	            "Constraints: write NO files and make no edits - this is a read-only consultation; answer in English; keep the answer under {} words.",
207	            inp.max_words
208	        ));
209	    } else {
210	        if !inp.purpose.is_empty() {
211	            parts.push(format!(
212	                "Review purpose: {}. {}",
213	                inp.purpose,
214	                presets::text(inp.purpose)
215	            ));
216	        }
217	        if !inp.open_findings.is_empty() {
218	            parts.push(render_open_findings(inp.open_findings));
219	        }
220	        parts.push(schema_block(inp));
221	        if inp.schema_transport == "prompt-only" {
222	            parts.push(format!("JSON Schema of the reply:{NL}{}", inp.schema_text));
223	        }
224	        parts.push(format!(
225	            "Constraints: write NO files and make no edits - this is a read-only consultation; answer in English; keep reply_markdown under {} words.",
226	            inp.max_words
227	        ));
228	    }
229	    // (wave 28c, D11) the re-read anchor: the last line before the consultation id.
230	    if !inp.reread_line.is_empty() {
231	        parts.push(inp.reread_line.to_string());
232	    }
233	    parts.push(format!("Consultation id: {}", inp.consult_id));
234	    parts.join(&format!("{NL}{NL}"))
235	}
