237	/// The longest first line of an ask the re-read anchor repeats whole (characters).
238	const REREAD_ASK_MAX: usize = 300;
239	
240	/// (wave 28c, D11 / F43-3, F44-6) A reviewer with a context window (`context_tokens` > 0) may
241	/// compact it mid-review, and a summary may lose the brief: its prompt ends by naming the brief
242	/// again - "Before you answer, re-read the brief: `<brief>`." - the last line before the
243	/// consultation id. (wave 28d, D7 / F50-2) Without a brief file the ask itself is repeated there.
244	/// (wave 28e, E4 / F54-4) A multi-line ask is not folded into one line: its FIRST line is repeated
245	/// whole (whitespace inside it folded; longer than 300 characters it is cut and points to the top
246	/// of the prompt), followed by the count of the remaining (non-blank) lines - " (+<n> more
247	/// lines)"; a one-line ask as before, cut at 300. `""` without a context window or an ask.
248	pub fn reread_line(context_tokens: i64, brief_ref: &str, prompt: &str) -> String {
249	    if context_tokens <= 0 {
250	        return String::new();
251	    }
252	    if !brief_ref.is_empty() {
253	        return format!("Before you answer, re-read the brief: `{brief_ref}`.");
254	    }
255	    let ask_lines: Vec<&str> = prompt
256	        .trim()
257	        .split('\n')
258	        .map(|l| l.strip_suffix('\r').unwrap_or(l))
259	        .filter(|l| !l.trim().is_empty())
260	        .collect();
261	    let Some(first) = ask_lines.first() else {
262	        return String::new();
263	    };
264	    let mut ask = c3_core::one_line(first);
265	    if ask.chars().count() > REREAD_ASK_MAX {
266	        ask = ask.chars().take(REREAD_ASK_MAX).collect::<String>()
267	            + "... (cut here: the whole ask is at the top of this prompt)";
268	    }
269	    let more = ask_lines.len() - 1;
270	    if more > 0 {
271	        ask.push_str(&format!(
272	            " (+{more} more {})",
273	            if more == 1 { "line" } else { "lines" }
274	        ));
275	    }
276	    format!("Before you answer, re-read the ask: {ask}")
277	}
278	
279	fn render_open_findings(open: &[OpenFinding]) -> String {
280	    let mut lines: Vec<String> = Vec::new();
281	    lines.push("Findings from earlier consultations in this task that are still open (id - status - locations - claim - trigger - verify):".to_string());
282	    for f in open {
283	        let mut line = format!(
284	            "- {} - {} - {} - {}",
285	            f.id,
286	            f.status,
287	            f.locations,
288	            c3_core::one_line(&f.claim)
289	        );
290	        let trigger = c3_core::one_line(&f.trigger);
291	        if !trigger.is_empty() {
292	            line.push_str(&format!(" - trigger: {trigger}"));
293	        }
294	        let verify = c3_core::one_line(&f.verification);
295	        if !verify.is_empty() {
296	            line.push_str(&format!(" - verify: {verify}"));
297	        }
298	        lines.push(line);
299	    }
300	    lines.push("Report each listed id in `prior_findings` as fixed, still-open or not-checked (unknown-id if you cannot find it). Do not file a still-open one again as a new finding unless the claim changed; when a new finding replaces a listed one (a split, a merge, a corrected claim), name the old id in its `supersedes`.".to_string());
301	    lines.join(NL)
302	}
