304	/// The `$schemaLines` block on its own, for a secondary turn (the timeout continuation on a
305	/// prompt-only transport re-sends the reply format, `codex-consult.ps1:3695`). `has_open` picks
306	/// the `prior_findings` line; `prompt_only` picks the first line's wording.
307	pub(crate) fn schema_lines(purpose: &str, has_open: bool, prompt_only: bool) -> String {
308	    // A minimal PromptInputs is enough: `schema_block` reads only `purpose`, whether
309	    // `open_findings` is empty, and `schema_transport`.
310	    let one = [OpenFinding {
311	        id: String::new(),
312	        status: String::new(),
313	        locations: String::new(),
314	        claim: String::new(),
315	        trigger: String::new(),
316	        verification: String::new(),
317	    }];
318	    let inp = PromptInputs {
319	        raw: false,
320	        purpose,
321	        prompt: "",
322	        brief_ref: "",
323	        brief_text: "",
324	        range: None,
325	        open_findings: if has_open { &one } else { &[] },
326	        schema_transport: if prompt_only {
327	            "prompt-only"
328	        } else {
329	            "output-schema"
330	        },
331	        schema_text: "",
332	        max_words: 0,
333	        consult_id: "",
334	        tools_line: "",
335	        role_line: "",
336	        context_line: "",
337	        prev_reply_line: "",
338	        reread_line: "",
339	    };
340	    schema_block(&inp)
341	}
342	
343	fn schema_block(inp: &PromptInputs) -> String {
344	    let prior_line = if inp.open_findings.is_empty() {
345	        "- prior_findings: an empty array (no earlier findings are open in this task)."
346	    } else {
347	        "- prior_findings: one entry {id, status, note} per id listed above; status fixed | still-open | not-checked | unknown-id."
348	    };
349	    let first = if inp.schema_transport == "prompt-only" {
350	        "Reply format: your final message must be exactly one JSON object - no code fence, no text before or after it - that satisfies the JSON Schema given at the end of this section (schema_version \"1\"). Field meaning:"
351	    } else {
352	        "Reply format: your final message must be exactly one JSON object matching the output schema you were given (schema_version \"1\"). Field meaning:"
353	    };
354	    let verdict_line = format!(
355	        "- verdict: ACCEPT, HOLD or REJECT for acceptance and diff-review consultations, ADVISE for every other consultation; this one takes {}. verdict_reason: one sentence.",
356	        presets::verdict_rule(inp.purpose)
357	    );
358	    let lines: Vec<&str> = vec![
359	        first,
360	        "- reply_markdown: your full answer in Markdown, answering every numbered question by number. This is what people read - a complete Markdown answer, but it lives INSIDE the JSON string, never as the message itself. The word limit below applies to reply_markdown only - never shorten, merge or drop findings to fit it.",
361	        "  If you want evidence you cannot obtain read-only, end reply_markdown with a section `## Requested checks` listing at most 5 items `RC1`..`RCn`, each ONE runnable command or procedure with its working directory, the permission it needs (read-only / workspace-write), the observation that would settle it, and a budget (time or scope); refer to a finding by its position in your findings array (`finding #2`), by an earlier id (`F04-1`) or by the invariant name. \"Investigate X\" is not a check. Omit the section if you need nothing.",
362	        "- findings: one item per concrete defect or risk you assert; an empty array is a valid answer.",
363	        "  - severity: blocker (must be fixed before acceptance) | major | minor | note.",
364	        "  - locations: every place the finding concerns, each {path, line} with the path relative to the repository root and line null when no single line applies; an empty array when the finding is not tied to a place (e.g. a missing interface).",
365	        "  - claim: the assertion, self-contained. trigger: the input or state that exposes it.",
366	        "  - evidence: what you ALREADY did to support the claim, one entry per source: kind (read-code: you read the code there | ran-command: you ran something and saw the result | inferred: deduced from other evidence | assumed: not checked), reference (the file, command or log you looked at), observation (what you saw there). At least one entry; use kind \"assumed\" when you checked nothing.",
367	        "  - verification: one step the coordinator can run next to confirm the claim (prospective - not what you already did).",
368	        "  - remedy: the fix you propose.",
369	        "  - supersedes: ids of earlier findings this one replaces (a split, a merge, a corrected claim); otherwise an empty array.",
370	        &verdict_line,
371	        prior_line,
372	        "- unproven: scenarios the evidence does not cover (an empty array if none).",
373	        "- first_run_checklist: for an acceptance consultation, what must be observed in logs or output on the first real run before an exit code 0 is believed; an empty array for other purposes.",
374	        "- schema_version: always \"1\".",
375	    ];
376	    lines.join(NL)
377	}
