486	    /// The plugin's `harness-fixes28e.ps1` ANCHOR (E4) asks: the first line whole, the rest
487	    /// counted; a first line over 300 characters cut with the pointer; the re-read line right
488	    /// before the consultation id.
489	    #[test]
490	    fn reread_anchor_keeps_the_first_line_and_counts_the_rest() {
491	        let ask1 = "Review app.txt for   typos.\nThen check the README.\n\n   And the CHANGELOG.  ";
492	        assert_eq!(
493	            reread_line(256000, "", ask1),
494	            "Before you answer, re-read the ask: Review app.txt for typos. (+2 more lines)"
495	        );
